/** Phrases with a number or a name in them. */
/** The nonlinear solve's and the buckling's messages, translated inside the notes that carry them (S5). */
const S5_MESSAGES: [RegExp, (m: RegExpExecArray) => string][] = [
  [/^Second order: unstable, the loads are past the critical ones \(αcr < 1\)\.$/, () => "อันดับสอง: ไม่เสถียร น้ำหนักบรรทุกเกินค่าวิกฤต (αcr < 1)."],
  [/^A mechanism once 1 members? went slack: nothing holds node (\S+) \(([^)]*)\)\.$/, (m) => `เป็นกลไกเมื่อชิ้นส่วน 1 ชิ้นหย่อน: ไม่มีอะไรยึดจุดต่อ ${m[1]} (${m[2]}).`],
  [/^A mechanism once (\d+) members? went slack: nothing holds node (\S+) \(([^)]*)\)\.$/, (m) => `เป็นกลไกเมื่อชิ้นส่วน ${m[1]} ชิ้นหย่อน: ไม่มีอะไรยึดจุดต่อ ${m[2]} (${m[3]}).`],
  [/^A mechanism once 1 members? went slack and (\d+) supports? lifted: nothing holds node (\S+) \(([^)]*)\)\.$/, (m) => `เป็นกลไกเมื่อชิ้นส่วน 1 ชิ้นหย่อนและจุดรองรับ ${m[1]} จุดยก: ไม่มีอะไรยึดจุดต่อ ${m[2]} (${m[3]}).`],
  [/^A mechanism once (\d+) members? went slack and (\d+) supports? lifted: nothing holds node (\S+) \(([^)]*)\)\.$/, (m) => `เป็นกลไกเมื่อชิ้นส่วน ${m[1]} ชิ้นหย่อนและจุดรองรับ ${m[2]} จุดยก: ไม่มีอะไรยึดจุดต่อ ${m[3]} (${m[4]}).`],
  [/^A mechanism at node (\S+) \(([^)]*)\)\.$/, (m) => `เป็นกลไกที่จุดต่อ ${m[1]} (${m[2]}).`],
  [/^The one-way members and supports did not settle: they go back to states already tried\.$/, () => "ชิ้นส่วนโครงสร้างและจุดรองรับที่ทำงานทิศทางเดียวไม่ลู่เข้า: กลับไปสู่สถานะที่เคยลองแล้ว."],
  [/^Not settled in (\d+) iterations\.$/, (m) => `ไม่ลู่เข้าใน ${m[1]} รอบ.`],
  [/^No buckling under these loads: the geometric stiffness only stiffens\.$/, () => "ไม่เกิดการโก่งเดาะภายใต้น้ำหนักบรรทุกเหล่านี้: ความแข็งเชิงเรขาคณิตมีแต่เพิ่มความแข็ง."],
  [/^No buckling mode: the compressed bars are held by what is round them\.$/, () => "ไม่มีโหมดการโก่งเดาะ: ชิ้นส่วนที่รับแรงอัดถูกยึดไว้โดยสิ่งที่อยู่รอบ ๆ."],
  [/^A mechanism in its last states\.$/, () => "กลไกการวิบัติในสถานะสุดท้าย."],
];
function s5msg(text: string): string {
  for (const [re, f] of S5_MESSAGES) { const x = re.exec(text); if (x) return f(x); }
  return text;
}

/** S5d: the parts of the imperfections', sheeting's and θ notes that vary. */
function s5dSeg(t: string): string {
  const a = /^φ up to 1\/(\d+) along (X|Y)(?: \(m = ([\d.]+)\))?$/.exec(t);
  if (a) return a[3] ? `φ สูงสุด 1/${a[1]} ตามแนว ${a[2]} (m = ${a[3]})` : `φ สูงสุด 1/${a[1]} ตามแนว ${a[2]}`;
  const b = /^no column along (X|Y)$/.exec(t);
  return b ? `ไม่มีเสาตามแนว ${b[1]}` : t;
}
